2	import type {
3	  RevealObserveOptions,
4	  TextRevealOptions,
5	  TextRevealInitOptions,
6	} from "../types/component.types.js";
7	import { DOM_CONFIG, MASKING } from "../config/dom.config.js";
8	import { ObserveManager } from "../manager/ObserveManager.js";
9	import { Animation } from "./Animation.js";
10	
11	const BR_PATTERN = /<br\s*\/?>/gi;
12	const MASKING_DISABLED_CLASS = "is-text-reveal-disabled";
13	
14	const REVEAL_KEY = MASKING.revealDatasetKey;
15	const MASK_KEY = MASKING.maskDatasetKey;
16	const REVEAL_INVIEW = MASKING.revealState.inview;
17	const REVEAL_DOWN = MASKING.revealState.down;
18	const MASK_READY = MASKING.maskState.ready;
19	
20	function clearReveal(element: HTMLElement): void {
21	  delete element.dataset[REVEAL_KEY];
22	}
23	
24	function setReveal(element: HTMLElement, value: string): void {
25	  element.dataset[REVEAL_KEY] = value;
26	}
27	
28	export class TextReveal extends Animation {
29	  private static _observeFrameId: number | null = null;
30	  private static readonly _observeManager = new ObserveManager();
31	
32	  static riseUp(
33	    target: string | Element | Element[],
34	    _options: TextRevealOptions = {},
35	  ): void {
36	    const elements = TextReveal.resolveManagedElements(target).filter(
37	      (element): element is HTMLElement =>
38	        element instanceof HTMLElement &&
39	        element.dataset[REVEAL_KEY] !== REVEAL_INVIEW,
40	    );
41	    if (elements.length === 0) return;
42	    elements.forEach((element) => {
43	      setReveal(element, REVEAL_INVIEW);
44	    });
45	  }
46	
47	  static setVisibleOn(
48	    target: string | Element | Element[],
49	    options: TextRevealOptions = {},
50	  ): void {
51	    TextReveal.riseUp(target, options);
52	  }
53	
54	  static setVisibleOff(
55	    target: string | Element | Element[],
56	    _options: TextRevealOptions = {},
57	  ): void {
58	    const elements = TextReveal.resolveManagedElements(target).filter(
59	      (element): element is HTMLElement => element instanceof HTMLElement,
60	    );
61	    if (elements.length === 0) return;
62	    elements.forEach((element) => {
63	      clearReveal(element);
64	      void element.getBoundingClientRect();
65	      setReveal(element, REVEAL_DOWN);
66	    });
67	  }
68	
69	  static prepare(
70	    target: string | Element | Element[],
71	    _options: TextRevealOptions = {},
72	  ): Element[] {
73	    const elements = TextReveal.resolveManagedElements(target).filter(
74	      (element): element is HTMLElement => element instanceof HTMLElement,
75	    );
76	    if (elements.length === 0) return [];
77	    elements.forEach((element) => {
78	      clearReveal(element);
79	    });
80	    return elements;
81	  }
82	
83	  static observe(
84	    target: string | Element | Element[],
85	    options: RevealObserveOptions = {},
86	  ): void {
87	    if (typeof document === "undefined") return;
88	    const targets = TextReveal._resolveObserveTargets(target, options);
89	    if (targets.length === 0) return;
90	    const onEnter =
91	      options.onEnter ?? ((element: Element) => TextReveal.riseUp(element));
92	    if (TextReveal._observeFrameId != null) {
93	      window.cancelAnimationFrame(TextReveal._observeFrameId);
94	    }
95	    TextReveal._observeFrameId = window.requestAnimationFrame(() => {
96	      TextReveal._observeFrameId = window.requestAnimationFrame(() => {
97	        TextReveal._observeFrameId = null;
98	        TextReveal._observeManager.observe(
99	          targets,
100	          {
101	            onEnter,
102	            onLeave: options.onLeave,
103	          },
104	          options,
105	        );
106	      });
107	    });
108	  }
109	
110	  static override resolveElements(
111	    target: string | Element | Element[],
112	  ): Element[] {
113	    if (target == null) return [];
114	    const resolve = (el: Element | null | undefined): Element[] => {
115	      if (el == null || typeof el.matches !== "function") return [];
116	      if (el.matches(MASKING.selector)) return [el];
117	      return [el, ...Array.from(el.querySelectorAll<Element>(MASKING.selector))];
118	    };
119	
120	    if (typeof target === "string") {
121	      const list = document.querySelectorAll(target);
122	      return Array.from(list).flatMap(resolve);
123	    }
124	    const arr = super.resolveElements(target);
125	    return arr.flatMap(resolve);
126	  }
127	
128	  static wrap(
129	    selector = `.${MASKING.wrapTargetClass}`,
130	    root?: ParentNode | null,
131	  ): void {
132	    if (typeof document === "undefined") return;
133	    const wrapperClass = MASKING.selector.slice(1);
134	    const scope = root ?? document;
135	    const elements = scope.querySelectorAll<HTMLElement>(selector);
136	    elements.forEach((el) => {
137	      if (el.querySelector(MASKING.selector)) {
138	        el.dataset[MASK_KEY] = MASK_READY;
139	        return;
140	      }
141	      const hasBr = el.querySelector("br") !== null;
142	      if (hasBr) {
143	        TextReveal.wrapMultiLine(el, wrapperClass);
144	      } else {
145	        TextReveal.wrapSingleLine(el, wrapperClass);
146	      }
147	      el.dataset[MASK_KEY] = MASK_READY;
148	    });
149	  }
150	
151	  private static wrapSingleLine(el: HTMLElement, wrapperClass: string): void {
152	    const outer = document.createElement("span");
153	    outer.className = wrapperClass;
154	    const inner = document.createElement("span");
155	    inner.className = MASKING.lineClass;
156	    while (el.firstChild) inner.appendChild(el.firstChild);
157	    outer.appendChild(inner);
158	    el.appendChild(outer);
159	  }
160	
161	  private static wrapMultiLine(el: HTMLElement, wrapperClass: string): void {
162	    const segments = el.innerHTML
163	      .split(BR_PATTERN)
164	      .map((s) => s.trim())
165	      .filter(Boolean);
166	    el.innerHTML = "";
167	    segments.forEach((segmentHtml) => {
168	      const outer = document.createElement("span");
169	      outer.className = wrapperClass;
170	      const inner = document.createElement("span");
171	      inner.className = MASKING.lineClass;
172	      inner.innerHTML = segmentHtml;
173	      outer.appendChild(inner);
174	      el.appendChild(outer);
175	    });
176	  }
177	
178	  static init(options: TextRevealInitOptions = {}): void {
179	    if (typeof document === "undefined") return;
180	
181	    TextReveal.dispose();
182	
183	    TextReveal.wrap(`.${MASKING.wrapTargetClass}`, options.root);
184	    if (!MASKING.enabled) {
185	      document.documentElement.classList.add(MASKING_DISABLED_CLASS);
186	      return;
187	    }
188	    document.documentElement.classList.remove(MASKING_DISABLED_CLASS);
189	
190	    const selector = options.selector ?? MASKING.selector;
191	    const excludeSelectors =
192	      options.excludeSelectors ?? DOM_CONFIG.maskingExcludeSelectors ?? [];
193	    const targets = TextReveal.resolveTargets(
194	      selector,
195	      excludeSelectors,
196	      options.root,
197	    );
198	    if (targets.length === 0) return;
199	    TextReveal.prepare(targets);
200	    TextReveal.observe(targets, options);
201	  }
202	
203	  static dispose(): void {
204	    if (TextReveal._observeFrameId != null) {
205	      window.cancelAnimationFrame(TextReveal._observeFrameId);
206	      TextReveal._observeFrameId = null;
207	    }
208	    TextReveal._observeManager.dispose();
209	    if (typeof document !== "undefined") {
210	      document.documentElement.classList.remove(MASKING_DISABLED_CLASS);
211	    }
212	  }
213	
214	  private static resolveTargets(
215	    selector: string,
216	    excludeSelectors: string[],
217	    root?: ParentNode | null,
218	  ): Element[] {
219	    const scope = root ?? document;
220	    const all = Array.from(scope.querySelectorAll(selector));
221	    const excludeRoots = excludeSelectors
222	      .map((sel) => scope.querySelector(sel))
223	      .filter((el): el is Element => el != null);
224	    const scoped =
225	      excludeRoots.length === 0
226	        ? all
227	        : all.filter((el) =>
228	      excludeRoots.every((root) => !root.contains(el)),
229	    );
230	    return [...new Set(scoped)];
231	  }
232	
233	  private static resolveManagedElements(
234	    target: string | Element | Element[],
235	  ): Element[] {
236	    if (typeof document === "undefined") return [];
237	    if (!MASKING.enabled) return [];
238	    if (target == null) return [];
239	    return TextReveal.resolveElements(target);
240	  }
241	
242	  private static _resolveObserveTargets(
243	    target: string | Element | Element[],
244	    options: RevealObserveOptions,
245	  ): Element[] {
246	    if (typeof target !== "string") {
247	      return TextReveal.resolveManagedElements(target);
248	    }
249	    const excludeSelectors =
250	      options.excludeSelectors ?? DOM_CONFIG.maskingExcludeSelectors ?? [];
251	    return TextReveal.resolveTargets(target, excludeSelectors, options.root);
252	  }
253	}
