19	const TITLE_LEFT_PAD = 0;
20	const BADGE_RIGHT_PAD = 0;
21	const TITLE_FONT = 34;
22	const TITLE_WEIGHT = 600;
23	const BADGE_FONT = 17;
24	const BADGE_PAD_H = 18;
25	const BADGE_PAD_V = 8;
26	const BADGE_BORDER = 1;
27	const BTN_FONT = 12;
28	const ROW1_LINE_HEIGHT = 22;
29	const ROW_GAP = 6;
30	const VIEW_MODAL_LABEL = "View Modal";
