38	function drawTitleBar(
39	  ctx: CanvasRenderingContext2D,
40	  proj: WorkProjectItem,
41	  width: number,
42	  imageHeight: number,
43	  renderOptions: WorkCardRenderOptions,
44	): void {
45	  const row1Y = imageHeight + META_TOP_PAD + ROW1_LINE_HEIGHT / 2;
46	  let maxTitleWidth = width - TITLE_LEFT_PAD;
47	  let badgeWidth = 0;
48	  let badgeX = 0;
49	  let badgeY = 0;
50	  let badgeText = "";
51	
52	  if (renderOptions.showCategory) {
53	    ctx.font = `500 ${BADGE_FONT}px ${FONT_UI}, sans-serif`;
54	    badgeText = formatWorkCategoryLabel(proj.category);
55	    const badgeTextWidth = ctx.measureText(badgeText).width;
56	    badgeWidth = Math.max(64, badgeTextWidth + BADGE_PAD_H * 2);
57	    const badgeHeight = BADGE_FONT + BADGE_PAD_V * 2;
58	    badgeX = width - BADGE_RIGHT_PAD - badgeWidth;
59	    badgeY = row1Y - badgeHeight / 2;
60	    maxTitleWidth = width - TITLE_LEFT_PAD - 10 - badgeWidth;
61	  }
62	
63	  ctx.font = `${TITLE_WEIGHT} ${TITLE_FONT}px ${FONT_KO}, sans-serif`;
64	  ctx.fillStyle = "rgba(255,255,255,.95)";
65	  ctx.textBaseline = "middle";
66	  let titleText = proj.title;
67	  if (ctx.measureText(titleText).width > maxTitleWidth) {
68	    while (
69	      titleText.length > 0 &&
70	      ctx.measureText(`${titleText}...`).width > maxTitleWidth
71	    ) {
72	      titleText = titleText.slice(0, -1);
73	    }
74	    titleText += "...";
75	  }
76	  ctx.fillText(titleText, TITLE_LEFT_PAD, row1Y, maxTitleWidth);
77	
78	  if (renderOptions.showCategory) {
79	    const badgeHeight = BADGE_FONT + BADGE_PAD_V * 2;
80	    ctx.strokeStyle = "rgba(255,255,255,0.35)";
81	    ctx.lineWidth = BADGE_BORDER;
82	    ctx.strokeRect(badgeX, badgeY, badgeWidth, badgeHeight);
83	    ctx.font = `500 ${BADGE_FONT}px ${FONT_UI}, sans-serif`;
84	    ctx.fillStyle = "rgba(255,255,255,0.88)";
85	    ctx.textAlign = "center";
86	    ctx.textBaseline = "middle";
87	    ctx.fillText(badgeText, badgeX + badgeWidth / 2, row1Y);
88	    ctx.textAlign = "left";
89	  }
90	
91	  if (!renderOptions.showViewModal) return;
92	  const row2Y = imageHeight + META_TOP_PAD + ROW1_LINE_HEIGHT + ROW_GAP + BTN_FONT / 2;
93	  ctx.font = `500 ${BTN_FONT}px ${FONT_UI}, sans-serif`;
94	  ctx.fillStyle = "rgba(255,255,255,.9)";
95	  ctx.textBaseline = "middle";
96	  ctx.fillText(VIEW_MODAL_LABEL, TITLE_LEFT_PAD, row2Y);
97	  const btnTextWidth = ctx.measureText(VIEW_MODAL_LABEL).width;
98	  ctx.strokeStyle = "rgba(255,255,255,0.65)";
99	  ctx.lineWidth = 1;
100	  ctx.beginPath();
101	  ctx.moveTo(TITLE_LEFT_PAD, row2Y + 7);
102	  ctx.lineTo(TITLE_LEFT_PAD + btnTextWidth, row2Y + 7);
103	  ctx.stroke();
104	}
105	
106	function drawImageCover(
107	  ctx: CanvasRenderingContext2D,
108	  image: HTMLImageElement,
109	  width: number,
110	  imageHeight: number,
111	): void {
112	  const ratio = width / imageHeight;
113	  const imageRatio = image.naturalWidth / image.naturalHeight;
114	  let sw: number;
115	  let sh: number;
116	  let sx: number;
117	  let sy: number;
118	  if (imageRatio > ratio) {
119	    sh = image.naturalHeight;
120	    sw = image.naturalHeight * ratio;
121	    sx = (image.naturalWidth - sw) / 2;
122	    sy = 0;
123	  } else {
124	    sw = image.naturalWidth;
125	    sh = image.naturalWidth / ratio;
126	    sx = 0;
127	    sy = (image.naturalHeight - sh) / 2;
128	  }
129	  ctx.drawImage(image, sx, sy, sw, sh, 0, 0, width, imageHeight);
130	}
131	
132	function drawCardToContext(
133	  ctx: CanvasRenderingContext2D,
134	  proj: WorkProjectItem,
135	  size: WorkCardSize,
136	  image?: HTMLImageElement | null,
137	  renderOptions: WorkCardRenderOptions = WORK_CARD_DEFAULT_RENDER_OPTIONS,
138	): void {
139	  const width = CANVAS_W;
140	  const height = Math.round((width * size.h) / size.w);
141	  const imageHeight = Math.round(width / IMAGE_ASPECT);
142	
143	  ctx.save();
144	  ctx.translate(0, height);
145	  ctx.scale(1, -1);
146	
147	  if (image && image.complete && image.naturalWidth > 0) {
148	    drawImageCover(ctx, image, width, imageHeight);
149	  } else {
150	    const gradient = ctx.createLinearGradient(0, 0, width, imageHeight);
151	    gradient.addColorStop(0, proj.bg);
152	    gradient.addColorStop(1, Helpers.lightenHex(proj.bg, 18));
153	    ctx.fillStyle = gradient;
154	    ctx.fillRect(0, 0, width, imageHeight);
155	    for (let index = 0; index < 6000; index += 1) {
156	      ctx.fillStyle = `rgba(255,255,255,${Math.random() * 0.04})`;
157	      ctx.fillRect(Math.random() * width, Math.random() * imageHeight, 1, 1);
158	    }
159	    const radial = ctx.createRadialGradient(
160	      width * 0.25,
161	      imageHeight * 0.2,
162	      0,
163	      width * 0.25,
164	      imageHeight * 0.2,
165	      width * 0.8,
166	    );
167	    radial.addColorStop(0, Helpers.hexToRgba(proj.ac, 0.28));
168	    radial.addColorStop(1, "rgba(0,0,0,0)");
169	    ctx.fillStyle = radial;
170	    ctx.fillRect(0, 0, width, imageHeight);
171	  }
172	
173	  drawTitleBar(ctx, proj, width, imageHeight, renderOptions);
174	  ctx.restore();
175	}
