4	  protected static resolveElements(
5	    target: string | Element | Element[],
6	  ): Element[] {
7	    if (typeof document === "undefined" || target == null) return [];
8	    if (typeof target === "string") {
9	      return Array.from(document.querySelectorAll(target));
10	    }
11	    if (Array.isArray(target)) {
12	      return target.filter((element): element is Element => element instanceof Element);
