449	      item.classList.toggle("is-complete", isComplete);
450	      item.classList.toggle("is-available", index <= furthestAccessibleStep);
451	
452	      if (!button) return;
453	      button.classList.toggle("is-framed", isCurrent);
454	      button.disabled = this._submitting || index > furthestAccessibleStep;
455	      button.setAttribute(
456	        "aria-label",
457	        `${this._resolveNavLabel(index)} ${this._resolveStepLabel(index)}`,
458	      );
