576	  private _syncChipList(
577	    node: HTMLElement,
578	    chipValues: ContactWizardChipData[],
579	  ): void {
580	    const previousPositions = this._captureChipPositions(node);
581	    const chipSet = new Set(chipValues.map((chip) => chip.key));
582	    const existingChips = new Map(
583	      Array.from(
584	        node.querySelectorAll<HTMLElement>(".no-wizard-overview__chip:not(.is-ghost)"),
585	      ).map((chip) => [chip.dataset.wizardChipKey ?? "", chip]),
586	    );
587	    let layoutChanged = false;
588	
589	    chipValues.forEach((value, index) => {
590	      const existingChip = existingChips.get(value.key);
591	      const chip = existingChip ?? this._createChip(value, index);
592	      this._cancelChipLeave(chip);
593	      this._syncChipContent(chip, value);
594	      chip.style.animationDelay = `${index * CONTACT_WIZARD.chipStaggerMs}ms`;
595	
596	      if (!existingChip) {
597	        node.append(chip);
598	        layoutChanged = true;
599	      }
600	    });
601	
602	    existingChips.forEach((chip, value) => {
603	      if (chipSet.has(value)) return;
604	      this._detachChipWithGhost(node, chip);
605	      layoutChanged = true;
606	    });
607	
608	    if (!layoutChanged) return;
609	    this._animateChipReflow(node, previousPositions);
610	  }
